SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.ar.root.first"."first" AS "first", "_root.ar.root.rest"."rest" AS "rest"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE (("public"."article"."id") >= (('2')::integer))   ORDER BY "id" ASC NULLS LAST LIMIT 3 ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  (SELECT  coalesce(json_agg("_sub_query"."rest" ORDER BY "ob_col_1" ASC NULLS LAST), '[]' )  FROM  (SELECT  "_unnest_table"."rest" AS "rest", "_unnest_table"."ob_col_1" AS "ob_col_1" FROM UNNEST(array_agg("rest" ), array_agg("root.ar.root.rest.pg.id" )) AS "_unnest_table"("rest", "ob_col_1")    ORDER BY "ob_col_1" ASC NULLS LAST LIMIT 2 ) AS "_sub_query"      ) AS "rest" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.rest.base"."id" AS "id"       ) AS "_e"      ) ) AS "rest", "_root.ar.root.rest.base"."id" AS "root.ar.root.rest.pg.id" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("_root.base"."id") = ("article_id"))   ORDER BY "id" ASC NULLS LAST LIMIT 5 OFFSET 1) AS "_root.ar.root.rest.base"    ORDER BY "root.ar.root.rest.pg.id" ASC NULLS LAST  ) AS "_root.ar.root.rest"      ) AS "_root.ar.root.rest" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  (SELECT  coalesce(json_agg("_sub_query"."first" ORDER BY "ob_col_1" ASC NULLS LAST), '[]' )  FROM  (SELECT  "_unnest_table"."first" AS "first", "_unnest_table"."ob_col_1" AS "ob_col_1" FROM UNNEST(array_agg("first" ), array_agg("root.ar.root.first.pg.id" )) AS "_unnest_table"("first", "ob_col_1")    ORDER BY "ob_col_1" ASC NULLS LAST LIMIT 2 ) AS "_sub_query"      ) AS "first" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.first.base"."id" AS "id"       ) AS "_e"      ) ) AS "first", "_root.ar.root.first.base"."id" AS "root.ar.root.first.pg.id" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("_root.base"."id") = ("article_id"))   ORDER BY "id" ASC NULLS LAST LIMIT 1 ) AS "_root.ar.root.first.base"    ORDER BY "root.ar.root.first.pg.id" ASC NULLS LAST  ) AS "_root.ar.root.first"      ) AS "_root.ar.root.first" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"      
